// Continuous (swept) contact test: does the segment from (ax,ay) to (bx,by)
// cross the brick inflated by the ball radius? Returns the time of first
// contact t in [0, 1], or null. Slab method (see noonat.github.io/intersect).
function sweptContact(ax, ay, bx, by, brick, r) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = bx - ax;
  const dy = by - ay;

  let tNear = -Infinity;
  let tFar = Infinity;

  if (Math.abs(dx) < 1e-9) {
    if (ax < minX || ax > maxX) return null;
  } else {
    let t1 = (minX - ax) / dx;
    let t2 = (maxX - ax) / dx;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tNear = Math.max(tNear, t1);
    tFar = Math.min(tFar, t2);
  }
  if (Math.abs(dy) < 1e-9) {
    if (ay < minY || ay > maxY) return null;
  } else {
    let t1 = (minY - ay) / dy;
    let t2 = (maxY - ay) / dy;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tNear = Math.max(tNear, t1);
    tFar = Math.min(tFar, t2);
  }

  if (tNear > tFar || tFar < 0 || tNear > 1) return null;
  return tNear < 0 ? 0 : tNear;
}
```

