edits.newText:
export function step(state, dt) {
  const { ball, paddle } = state;

  // Position before the step: the swept brick test needs the travelled
  // segment, not just the arrival sample (tunneling).
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

edits.oldText:
  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

edits.newText:
  // Bricks: swept detection between the previous and the current position,
  // then a per-face bounce on the least-penetration axis (both axes on a
  // corner), pushing the ball back out of the brick.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    const t = sweptContact(prevX, prevY, ball.x, ball.y, brick, ball.r);
    if (t === null) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Contact point of the first touch along the swept segment.
    const cx = prevX + (ball.x - prevX) * t;
    const cy = prevY + (ball.y - prevY) * t;
    const pen = penetration({ x: cx, y: cy, r: ball.r }, brick);

    if (pen.x < pen.y) {
      ball.vx = -ball.vx;
      ball.x = ball.vx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
    } else if (pen.y < pen.x) {
      ball.vy = -ball.vy;
      ball.y = ball.vy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
    } else {
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      ball.x = ball.vx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
      ball.y = ball.vy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

