test('step: brick bounce on a seam flips vy exactly once', () => {
  const state = createState(1);
  // Two stacked bricks; the seam gap (8 px) is smaller than the ball diameter
  // (14 px), so a ball centred on the seam overlaps BOTH bricks through their
  // shared faces at once. Both penetrations are vertical, so a resolver that
  // flips vy per brick flips it twice and the ball keeps going up (ghost
  // collision). The pass must bounce each axis at most once.
  state.bricks = [
