  ];
  state.ball = { x: 136, y: 124, r: BALL_R, vx: 0, vy: -60 };

  step(state, 1 / 60);

  assert.equal(state.ball.vy, 60, 'vy must be flipped exactly once');
  assert.equal(state.ball.vx, 0, 'vx must stay untouched');
});

