cd game && node -e "
import('./neon.js').then(m => {
  // 20 s of gameplay at level 6, mixing nominal and hiccup frames.
  const state = m.createState(6);
  let frames = 0, bounces = 0, lost = 0;
  for (let t = 0; t < 20; t += 1/60) {
    const dt = (frames % 97 === 0) ? 0.05 : 1/60; // occasional hiccup
    const lostFrame = m.step(state, dt);
    frames++;
    if (lostFrame) { lost++; m.ball.vy = -Math.abs(m.ball.vy); } // pretend paddle save
    if (!Number.isFinite(state.ball.x) || !Number.isFinite(state.ball.y)) throw new Error('NaN position!');
  }
  const dead = state.bricks.filter(b => !b.alive).length;
  console.log('frames', frames, '| lost-frames', lost, '| bricks dead', dead + '/' + state.bricks.length, '| score', state.score, '| ball', state.ball.x.toFixed(1), state.ball.y.toFixed(1), 'vx', state.ball.vx.toFixed(1), 'vy', state.ball.vy.toFixed(1));
  // Ball always inside the field horizontally
  if (state.ball.x - state.ball.r < -1 || state.ball.x + state.ball.r > m.WIDTH + 1) throw new Error('ball out of field x');
  console.log('OK');
})"

